//! Cargo-driven `iernonce.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x73d90000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ff11000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ff11000000u64)),
        o => panic!("iernonce-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["import:advapi32", "import:msvcrt", "import:gdi32", "import:ole32", "import:shell32", "import:shlwapi", "import:kernel32", "import:user32", "import:ntdll", "toolchain:libc++.a", "toolchain:libc++abi.a", "toolchain:libunwind.a", "engine:c:stdc++compat", "import:kernel32_vista", "toolchain:libmingwex.a", "body", "engine:oldnames", "engine:pseh", "engine:chkstk"],
        "x86_64" => &["import:advapi32", "import:msvcrt", "import:gdi32", "import:ole32", "import:shell32", "import:shlwapi", "import:kernel32", "import:user32", "import:ntdll", "toolchain:libc++.a", "toolchain:libc++abi.a", "toolchain:libunwind.a", "engine:c:stdc++compat", "import:kernel32_vista", "toolchain:libmingwex.a", "body", "engine:oldnames", "engine:pseh"],
        "aarch64" => &["import:advapi32", "import:msvcrt", "import:gdi32", "import:ole32", "import:shell32", "import:shlwapi", "import:kernel32", "import:user32", "import:ntdll", "toolchain:libc++.a", "toolchain:libc++abi.a", "toolchain:libunwind.a", "engine:c:stdc++compat", "import:kernel32_vista", "toolchain:libmingwex.a", "body", "engine:oldnames", "engine:pseh", "engine:chkstk"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = match arch.as_str() {
        "x86" => &[
            "@build/dll/win32/iernonce",
            "dll/win32/iernonce",
            "@std",
            "vendor/opengl-headers/include",
            "vendor/libdxg/include",
            "dll/win32/iernonce/include",
            "sdk/lib/pseh/include",
            ".build-tools/llvm-mingw/i686-w64-mingw32/include/c++/v1",
            ".build-tools/llvm-mingw/lib/clang/19/include",
            ".build-tools/llvm-mingw/i686-w64-mingw32/include",
        ],
        "x86_64" => &[
            "@build/dll/win32/iernonce",
            "dll/win32/iernonce",
            "@std",
            "vendor/opengl-headers/include",
            "vendor/libdxg/include",
            "dll/win32/iernonce/include",
            "sdk/lib/pseh/include",
            ".build-tools/llvm-mingw/x86_64-w64-mingw32/include/c++/v1",
            ".build-tools/llvm-mingw/lib/clang/19/include",
            ".build-tools/llvm-mingw/x86_64-w64-mingw32/include",
        ],
        "aarch64" => &[
            "@build/dll/win32/iernonce",
            "dll/win32/iernonce",
            "@std",
            "vendor/opengl-headers/include",
            "vendor/libdxg/include",
            "dll/win32/iernonce/include",
            "sdk/lib/pseh/include",
            ".build-tools/llvm-mingw/aarch64-w64-mingw32/include/c++/v1",
            ".build-tools/llvm-mingw/lib/clang/19/include",
            ".build-tools/llvm-mingw/aarch64-w64-mingw32/include",
        ],
        _ => unreachable!(),
    };
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "UNICODE",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_UNICODE",
        "_WIN32_WINNT=0x502",
        "__USE_CRTIMP",
    ];

    Linker::new(target_json)
        .c_from_compile_db("iernonce_shims", &["dll/win32/iernonce/dialog.cpp", "dll/win32/iernonce/iernonce.cpp", "dll/win32/iernonce/registry.cpp"])
        .rc("dll/win32/iernonce/iernonce.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/iernonce/iernonce.spec", "iernonce.dll")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("dll/win32/shell32/shell32.spec", "shell32.dll", "shell32")
        .import_lib("dll/win32/shlwapi/shlwapi.spec", "shlwapi.dll", "shlwapi")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
